#!/bin/sh
# Regenerates the iOS and Android app icons from assets/brand/app-icon.svg
# (the football, generated by scripts/app-icon-svg.py) and the launch screen
# logo from assets/brand/logo-lockup-dark.svg (scripts/brand-svg.py).
# iOS gets a single 1024 icon; Android gets square and round mipmaps.
# Needs Google Chrome (renders the SVG) and Python 3 with Pillow (resizes).
set -e
here=$(cd "$(dirname "$0")/.." && pwd)
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
chrome="/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
for variant in app-icon; do
  printf '<html><body style="margin:0">%s</body></html>' "$(cat "$here/assets/brand/$variant.svg")" > "$work/$variant.html"
  "$chrome" --headless=new --disable-gpu --hide-scrollbars --force-device-scale-factor=1 \
    --window-size=1024,1024 --screenshot="$work/$variant.png" "file://$work/$variant.html" 2>/dev/null
done
python3 - "$work" "$here" <<'PY'
import glob, json, os, sys
from PIL import Image, ImageDraw
work, root = sys.argv[1], sys.argv[2]
light = Image.open(os.path.join(work, "app-icon.png")).convert("RGB")  # iOS rejects alpha

ios = os.path.join(root, "ios/FutCareer/Images.xcassets/AppIcon.appiconset")
for old in glob.glob(os.path.join(ios, "AppIcon-*.png")):
    os.remove(old)
light.save(os.path.join(ios, "AppIcon-1024.png"), optimize=True)
json.dump({
    "images": [
        {"filename": "AppIcon-1024.png", "idiom": "universal", "platform": "ios", "size": "1024x1024"},
    ],
    "info": {"author": "xcode", "version": 1},
}, open(os.path.join(ios, "Contents.json"), "w"), indent=2)

def masked(size, shape):
    icon = light.resize((size, size), Image.LANCZOS).convert("RGBA")
    mask = Image.new("L", (size * 4, size * 4), 0)
    draw = ImageDraw.Draw(mask)
    if shape == "round":
        draw.ellipse((0, 0, size * 4 - 1, size * 4 - 1), fill=255)
    else:
        draw.rounded_rectangle((0, 0, size * 4 - 1, size * 4 - 1), radius=size * 4 // 5, fill=255)
    icon.putalpha(mask.resize((size, size), Image.LANCZOS))
    return icon

res = os.path.join(root, "android/app/src/main/res")
for folder, size in {"mdpi": 48, "hdpi": 72, "xhdpi": 96, "xxhdpi": 144, "xxxhdpi": 192}.items():
    masked(size, "square").save(os.path.join(res, "mipmap-" + folder, "ic_launcher.png"), optimize=True)
    masked(size, "round").save(os.path.join(res, "mipmap-" + folder, "ic_launcher_round.png"), optimize=True)

print("app icons written")
PY

# Launch screen logo: the dark-surface lockup on a transparent background,
# 240pt wide (iOS imageset @1x-3x, Android drawable densities).
printf '<html><body style="margin:0;background:transparent">%s</body></html>' \
  "$(sed 's/<svg /<svg width="1440" /' "$here/assets/brand/logo-lockup-dark.svg")" > "$work/launch.html"
"$chrome" --headless=new --disable-gpu --hide-scrollbars --force-device-scale-factor=1 \
  --default-background-color=00000000 --window-size=1440,262 \
  --screenshot="$work/launch.png" "file://$work/launch.html" 2>/dev/null
python3 - "$work" "$here" <<'PY'
import json, os, sys
from PIL import Image
work, root = sys.argv[1], sys.argv[2]
master = Image.open(os.path.join(work, "launch.png")).convert("RGBA")
master = master.crop(master.getbbox())
def scaled(width):
    return master.resize((width, round(master.height * width / master.width)), Image.LANCZOS)
ios = os.path.join(root, "ios/FutCareer/Images.xcassets/LaunchLogo.imageset")
os.makedirs(ios, exist_ok=True)
images = []
for scale in (1, 2, 3):
    name = "LaunchLogo@%dx.png" % scale
    scaled(240 * scale).save(os.path.join(ios, name), optimize=True)
    images.append({"idiom": "universal", "filename": name, "scale": "%dx" % scale})
json.dump({"images": images, "info": {"author": "xcode", "version": 1}}, open(os.path.join(ios, "Contents.json"), "w"), indent=2)
res = os.path.join(root, "android/app/src/main/res")
for folder, factor in {"mdpi": 1, "hdpi": 1.5, "xhdpi": 2, "xxhdpi": 3, "xxxhdpi": 4}.items():
    os.makedirs(os.path.join(res, "drawable-" + folder), exist_ok=True)
    scaled(round(240 * factor)).save(os.path.join(res, "drawable-" + folder, "launch_logo.png"), optimize=True)
print("launch logo written")
PY
